import{_ as r,C as l,c as i,o as g,a3 as n,G as s,j as o,a as t}from"./chunks/framework.Dokpd4od.js";const T=JSON.parse('{"title":"Manage allocations","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/allocations/manage-allocations.md","filePath":"master/human-resources/time-off/allocations/manage-allocations.md","lastUpdated":1792041590000}'),p={name:"master/human-resources/time-off/allocations/manage-allocations.md"};function m(d,e,h,c,u,f){const a=l("ImagePopup");return g(),i("div",null,[e[0]||(e[0]=n('<h1 id="manage-allocations" tabindex="-1">Manage allocations <a class="header-anchor" href="#manage-allocations" aria-label="Permalink to &quot;Manage allocations&quot;">​</a></h1><p>Management lists the allocations of all employees. Here a manager creates allocations for others, approves or refuses requests for days, and edits existing ones. Use it at the start of each year to give every employee their days.</p><blockquote><p><strong>In simple words:</strong> Create the allocation for the employee, then approve it. The days then count in their balance.</p></blockquote><p>Open <code>Time Off → Management → Allocation</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>The employee exists. See <a href="./../../employees/employees/add-employee.html">Employees</a>.</li><li>The leave type exists. See <a href="./../setup/time-off-types.html">Leave types</a>.</li></ul></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page is titled <strong>Allocations</strong>. It opens on the <strong>Waiting For Me</strong> tab.</p><ul><li><strong>Tabs:</strong> <strong>Default</strong>, <strong>Waiting For Me</strong>, <strong>Second Approval</strong> and <strong>Approved</strong>.</li><li><strong>Three-dot menu next to the tabs:</strong> preset views <strong>Currently Valid</strong>, <strong>My Team</strong>, <strong>My Department</strong> and <strong>Refused</strong>.</li><li><strong><em>Columns:</em></strong> <strong>Employee</strong>, <strong>Time Off Type</strong>, <strong>Amount</strong>, <strong>Allocation Type</strong>, <strong>Status</strong>.</li><li><strong>Group by:</strong> <strong>Employee Name</strong>, <strong>Time Off Type</strong>, <strong>Allocation Type</strong>, <strong>Status</strong>, <strong>Start Date</strong>.</li></ul><p>Click <strong>Default</strong> to see every allocation. A row opens the <strong>View</strong> page.</p>',9)),s(a,{src:"/images1/time-off/alloc_mgt_list.png",alt:"Allocations list on the Default tab with all rows and columns Employee, Time Off Type, Amount, Allocation Type and Status, including Priya Sharma with 12.0000 Paid Time Off and 5.0000 Sick Time Off"}),e[1]||(e[1]=o("h2",{id:"create-an-allocation",tabindex:"-1"},[t("Create an allocation "),o("a",{class:"header-anchor",href:"#create-an-allocation","aria-label":'Permalink to "Create an allocation"'},"​")],-1)),e[2]||(e[2]=o("p",null,[t("Priya Sharma has no days yet. Give her 12 days of "),o("strong",null,"Paid Time Off"),t(".")],-1)),e[3]||(e[3]=o("ol",null,[o("li",null,[t("Open "),o("code",null,"Time Off → Management → Allocation"),t(". Click "),o("strong",null,"New Allocation"),t(".")])],-1)),s(a,{src:"/images1/time-off/alloc_mgt_create_empty.png",alt:"Create Allocation form with the State bar on To Approve, empty Name, Time Off Type and Employee Name, Regular selected, Date From Oct 13 2026, Date To No Limit and Allocation 0"}),e[4]||(e[4]=n('<h3 id="allocation-details" tabindex="-1">Allocation details <a class="header-anchor" href="#allocation-details" aria-label="Permalink to &quot;Allocation details&quot;">​</a></h3><ol start="2"><li>Type <strong>Paid Time Off 2026</strong> in <strong>Name</strong>. Aureus does not fill it in.</li><li>Choose <strong>Paid Time Off</strong> in <strong>Time Off Type</strong>.</li><li>Choose <strong>Priya Sharma</strong> in <strong>Employee Name</strong>.</li><li>Keep <strong>Allocation Type</strong> on <strong>Regular</strong>.</li></ol><ul><li><strong><em>Name:</em></strong> Required. A label for the allocation.</li><li><strong><em>Time Off Type:</em></strong> Required. The leave type that receives the days.</li><li><strong><em>Employee Name:</em></strong> Required. The person who receives the days.</li><li><strong><em>Allocation Type:</em></strong> Required. Keep <strong>Regular</strong>.</li></ul><h3 id="validity-period" tabindex="-1">Validity period <a class="header-anchor" href="#validity-period" aria-label="Permalink to &quot;Validity period&quot;">​</a></h3><ol start="6"><li>Set <strong>Date From</strong> to <strong>Oct 1, 2026</strong>. It starts on today&#39;s date.</li><li>Leave <strong>Date To</strong> empty. It shows <strong>No Limit</strong>, so the allocation is open ended.</li></ol><h3 id="days-and-reason" tabindex="-1">Days and reason <a class="header-anchor" href="#days-and-reason" aria-label="Permalink to &quot;Days and reason&quot;">​</a></h3><ol start="8"><li>Type <strong>12</strong> in <strong>Allocation</strong>. The field shows <strong>Number of Days</strong>.</li><li>Type <strong>Annual leave 2026</strong> in <strong>Reason</strong>.</li></ol>',7)),s(a,{src:"/images1/time-off/alloc_mgt_create_filled.png",alt:"Filled Create Allocation form: Name Paid Time Off 2026, Paid Time Off, Priya Sharma, Regular, Date From Oct 1 2026, Date To No Limit, 12 Number of Days, reason Annual leave 2026"}),e[5]||(e[5]=n('<ol start="10"><li>Click <strong>Create</strong>. A <strong>Time Off created</strong> message appears. The app opens the allocation <strong>View</strong> page. The allocation starts as <strong>To Approve</strong>.</li></ol><h2 id="approve-the-allocation" tabindex="-1">Approve the allocation <a class="header-anchor" href="#approve-the-allocation" aria-label="Permalink to &quot;Approve the allocation&quot;">​</a></h2><p>New allocations start as <strong>To Approve</strong>. Approve the allocation so the days count.</p><ol><li>Open <code>Time Off → Management → Allocation</code>. Click the <strong>Default</strong> tab.</li><li>Click the three-dot icon on the row of Priya Sharma. Click <strong>Approve</strong>.</li></ol>',4)),s(a,{src:"/images1/time-off/alloc_mgt_row_actions.png",alt:"Row menu on the Priya Sharma allocation, 12.0000, To Approve, with View, Edit, Delete, Approve and Refuse in that order"}),e[6]||(e[6]=o("ol",{start:"3"},[o("li",null,[t("Check that the "),o("strong",null,"Status"),t(" column shows "),o("strong",null,"Approved"),t(".")])],-1)),s(a,{src:"/images1/time-off/alloc_mgt_approved.png",alt:"Allocations list filtered by Priya showing Priya Sharma, Paid Time Off, 12.0000, Regular, status Approved"}),e[7]||(e[7]=n('<p>The days now count. Priya can request leave of this type. The <a href="./../requests/my-time.html">My Time</a> cards show the balance of the logged in employee. When Priya signs in, her <strong>Paid Time Off</strong> card shows <strong>12.0</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Approve</strong> (row menu): sets the status to <strong>Approved</strong>. The row menu hides it when the allocation is already approved.</li><li><strong>Refuse</strong> (row menu): sets the status to <strong>Refused</strong>. The days never count.</li><li><strong>View</strong>, <strong>Edit</strong>, <strong>Delete</strong>: open, change or remove the allocation.</li></ul><p>The row menu lists them in this order: <strong>View</strong>, <strong>Edit</strong>, <strong>Delete</strong>, <strong>Approve</strong>, <strong>Refuse</strong>.</p><p>The <strong>View</strong> and <strong>Edit</strong> pages show a <strong>State</strong> bar with <strong>To Approve</strong> and <strong>Approved</strong>. The edit page header can show <strong>Approved</strong>, <strong>Refuse</strong> and <strong>Mark as Ready to Confirm</strong>. Use the row menu for the quickest approval. <strong>Mark as Ready to Confirm</strong> returns a refused allocation to <strong>To Approve</strong>. <strong>Refuse</strong> is hidden once an allocation is refused.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only approved allocations add to the balance. Refuse an allocation if it was entered by mistake, or delete it.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Time off allocations</a></li><li><a href="./my-allocation.html">My allocation</a></li><li><a href="./../requests/manage-requests.html">Manage requests</a></li><li><a href="./../setup/time-off-types.html">Leave types</a></li><li><a href="./../reporting/by-employees.html">By Employees report</a></li></ul>',8))])}const v=r(p,[["render",m]]);export{T as __pageData,v as default};
